package com.android.quickstep.util

import android.content.Context
import com.android.launcher3.concurrent.annotations.Ui
import com.android.launcher3.dagger.ApplicationContext
import com.android.launcher3.dagger.LauncherAppSingleton
import com.android.launcher3.hecker.HeckerAppLockState
import com.android.launcher3.util.DaggerSingletonTracker
import com.android.launcher3.util.LooperExecutor
import javax.inject.Inject

/** Keeps the existing recents injection contract on Android 17's native App Lock. */
@LauncherAppSingleton
class AxSandboxState
@Inject
constructor(
    @ApplicationContext context: Context,
    @Ui uiExecutor: LooperExecutor,
    lifecycle: DaggerSingletonTracker,
) : HeckerAppLockState(context, uiExecutor) {
    init {
        lifecycle.addCloseable { close() }
    }
}
